begin;
do $$
declare
  v_site_id uuid;
  v_page_id uuid;
  v_document_id uuid;
  v_document jsonb;
begin
  select id into v_site_id from website.sites where site_key='marktone-main' limit 1;
  if v_site_id is null then raise exception 'marktone_main_site_not_found'; end if;
  select id into v_page_id from website.pages where site_id=v_site_id and is_home and status<>'archived' limit 1;
  if v_page_id is null then raise exception 'marktone_home_page_not_found'; end if;

  v_document:=private_app.website_builder_validate_document(
    $document${"schemaVersion":1,"settings":{"contentWidth":"wide","background":"#ffffff","customCss":":root{--mt-home-navy:#071d37;--mt-home-navy-2:#0b2f53;--mt-home-teal:#08b8b1;--mt-home-cyan:#20c6cf;--mt-home-yellow:#ffc928;--mt-home-ink:#0a2540;--mt-home-muted:#64748b;--mt-home-line:#e4ecf2}\nhtml{scroll-behavior:smooth}\n.mt-home-hero-row{position:relative;overflow:hidden;padding-top:150px!important;padding-bottom:74px!important;background:radial-gradient(circle at 10% 15%,rgba(255,201,40,.20),transparent 25%),radial-gradient(circle at 92% 18%,rgba(8,184,177,.20),transparent 30%),linear-gradient(180deg,#f7fbfd 0%,#fff 72%)!important}\n.mt-home-hero-row:before{content:\"\";position:absolute;inset:0;background-image:linear-gradient(rgba(7,29,55,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(7,29,55,.035) 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,black,transparent 75%);pointer-events:none}\n.mt-home-hero-row>div{position:relative;z-index:1}\n.mt-home-hero-heading{padding:8px 0!important}.mt-home-hero-heading h1{font-size:clamp(46px,5.2vw,76px)!important;line-height:1.12!important;letter-spacing:-.045em!important;color:var(--mt-home-ink)!important;max-width:720px;margin-bottom:14px!important}.mt-home-hero-heading p:first-child{display:inline-flex!important;align-items:center;gap:9px;background:#e8fbf8;color:#087f7a!important;border:1px solid #bcebe5;border-radius:999px;padding:8px 13px!important;font-size:11px!important;font-weight:900!important}.mt-home-hero-heading p:last-child{max-width:680px;color:var(--mt-home-muted)!important;font-size:18px!important;line-height:1.9!important}.mt-home-hero-heading span{display:block!important;margin-top:8px!important;color:var(--mt-home-teal)!important;font-size:clamp(34px,4vw,58px)!important}\n.mt-home-hero-actions{padding:5px 0!important}.mt-home-hero-actions a:first-child{background:linear-gradient(135deg,var(--mt-home-teal),#087f9c)!important;border-color:transparent!important;color:white!important;border-radius:12px!important;box-shadow:0 16px 34px rgba(8,184,177,.24)!important}.mt-home-hero-actions a:last-child{border-color:#cbd9e3!important;color:var(--mt-home-ink)!important;border-radius:12px!important;background:white!important}\n.mt-hero-chips{display:flex;gap:10px;flex-wrap:wrap;padding-top:4px}.mt-hero-chips span{font-size:11px;color:#53687c;background:#fff;border:1px solid #e0e9ef;border-radius:999px;padding:8px 11px;box-shadow:0 8px 25px rgba(16,44,70,.05)}\n.mt-hero-dashboard{padding:0!important}.mt-dashboard{direction:rtl;border:1px solid rgba(26,75,108,.13);border-radius:24px;background:#fff;box-shadow:0 35px 90px rgba(7,35,65,.17);overflow:hidden;transform:perspective(1200px) rotateY(-2deg) rotateX(1deg)}\n.mt-dashboard-bar{height:46px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:0 17px;border-bottom:1px solid #e7edf2;background:#fbfdfe}.mt-dashboard-bar>div{direction:ltr;display:flex;gap:5px}.mt-dashboard-bar i{width:7px;height:7px;border-radius:50%;background:#d9e2e8}.mt-dashboard-bar i:first-child{background:var(--mt-home-yellow)}.mt-dashboard-bar i:nth-child(2){background:var(--mt-home-teal)}.mt-dashboard-bar strong{font-size:10px;text-align:center;color:#708196}.mt-dashboard-bar>span{font-size:8px;color:#087f7a;background:#dff8f3;border-radius:999px;padding:4px 7px}\n.mt-dashboard-body{display:grid;grid-template-columns:100px 1fr;min-height:430px}.mt-dashboard-body aside{background:linear-gradient(180deg,#071d37,#0a2b4a);color:#fff;padding:17px 10px;display:flex;flex-direction:column;gap:7px}.mt-dashboard-body aside>b{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,var(--mt-home-teal),var(--mt-home-yellow));color:#071d37;margin:0 auto 13px;font-size:16px}.mt-dashboard-body aside span{padding:8px;border-radius:8px;font-size:8px;color:#a9bbc9}.mt-dashboard-body aside span.active{background:#ffffff17;color:#fff}.mt-dashboard-body>section{padding:22px;background:#f7fafc;min-width:0}.mt-dashboard-body>section>header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.mt-dashboard-body header small{font-size:8px;color:#7a8b99}.mt-dashboard-body header h3{font-size:14px;margin:4px 0;color:#102f4b}.mt-dashboard-body header em{font-style:normal;font-size:8px;color:#657786;background:#fff;border:1px solid #e2e9ee;border-radius:8px;padding:6px 8px}\n.mt-dashboard-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:17px}.mt-dashboard-kpis article{background:#fff;border:1px solid #e7edf2;border-radius:12px;padding:12px}.mt-dashboard-kpis small,.mt-dashboard-kpis span{display:block;font-size:7px;color:#82909d}.mt-dashboard-kpis strong{display:block;font-size:23px;color:#0b2c4a;margin:5px 0}.mt-dashboard-kpis span{color:#0b9d88}\n.mt-dashboard-grid{display:grid;grid-template-columns:1.35fr .65fr;gap:10px;margin-top:10px}.mt-dashboard-grid article{background:#fff;border:1px solid #e7edf2;border-radius:13px;padding:13px}.mt-dashboard-grid article>div:first-child{display:flex;justify-content:space-between}.mt-dashboard-grid b{font-size:9px;color:#193d59}.mt-dashboard-grid small{font-size:7px;color:#8b9aa6}.mt-chart{height:145px;position:relative;margin-top:12px;border-bottom:1px solid #dfe7ed;background:repeating-linear-gradient(to top,#eef3f6 0 1px,transparent 1px 36px)}.mt-chart i{position:absolute;bottom:0;width:8%;border-radius:7px 7px 0 0;background:linear-gradient(180deg,#23c8ce,#0b9f9a);opacity:.26}.mt-chart i:nth-child(1){height:28%;right:3%}.mt-chart i:nth-child(2){height:45%;right:20%}.mt-chart i:nth-child(3){height:40%;right:37%}.mt-chart i:nth-child(4){height:66%;right:54%}.mt-chart i:nth-child(5){height:58%;right:71%}.mt-chart i:nth-child(6){height:85%;right:88%}.mt-chart span{position:absolute;inset:24px 8px 20px;background:linear-gradient(150deg,transparent 49%,var(--mt-home-teal) 50% 52%,transparent 53%);clip-path:polygon(0 75%,17% 58%,33% 65%,52% 36%,68% 48%,100% 8%,100% 14%,68% 54%,52% 43%,33% 72%,17% 65%,0 83%)}.mt-pipeline-card ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:9px}.mt-pipeline-card li{display:flex;justify-content:space-between;align-items:center;padding-bottom:8px;border-bottom:1px solid #edf1f4}.mt-pipeline-card li span{font-size:8px;color:#667b8d}.mt-pipeline-card li b{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:#e8f8f6;color:#087f7a}\n.mt-trust-row{padding:20px 0!important;background:#fff!important;border-top:1px solid #edf2f5;border-bottom:1px solid #edf2f5}.mt-trust-strip{text-align:center}.mt-trust-strip p{margin:0 0 14px;color:#6f8090;font-size:11px;font-weight:800}.mt-trust-strip div{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}.mt-trust-strip span{min-width:120px;padding:10px 13px;border:1px solid #e4ebf0;border-radius:10px;background:#fbfcfd;color:#425b70;font-size:10px}\n.mt-section-title{padding-top:18px!important;padding-bottom:8px!important}.mt-section-title h2{font-size:clamp(34px,4vw,54px)!important;line-height:1.25!important;color:var(--mt-home-ink)!important}.mt-section-title p:first-child{color:var(--mt-home-teal)!important;font-weight:900!important}.mt-section-title p:last-child{max-width:760px;margin-inline:auto;color:var(--mt-home-muted)!important;font-size:16px!important;line-height:1.85!important}\n.mt-solutions-row{padding-bottom:90px!important}.mt-solution-growth,.mt-solution-sales,.mt-solution-ops,.mt-solution-web{padding:0!important;--gold:var(--mt-home-teal)}.mt-solution-growth>a,.mt-solution-sales>a,.mt-solution-ops>a,.mt-solution-web>a{min-height:270px!important;padding:28px!important;border-radius:20px!important;border:1px solid #dfe8ee!important;background:#fff!important;box-shadow:0 18px 55px rgba(7,40,70,.07)!important;transition:.25s!important}.mt-solution-growth>a:hover,.mt-solution-sales>a:hover,.mt-solution-ops>a:hover,.mt-solution-web>a:hover{transform:translateY(-7px);box-shadow:0 28px 70px rgba(7,40,70,.13)!important;border-color:#acdeda!important}.mt-solution-growth{--gold:#08b8b1}.mt-solution-sales{--gold:#2987f5}.mt-solution-ops{--gold:#7c5ce7}.mt-solution-web{--gold:#f4b400}\n.mt-command-row{position:relative;overflow:hidden;background:radial-gradient(circle at 15% 10%,rgba(255,201,40,.15),transparent 27%),radial-gradient(circle at 86% 80%,rgba(32,198,207,.14),transparent 30%),linear-gradient(135deg,#06182e,#0b3154)!important;color:white!important;padding:95px 0!important}.mt-command-title{padding:12px 0!important}.mt-command-title h2{color:#fff!important;font-size:clamp(38px,4.5vw,62px)!important;line-height:1.22!important}.mt-command-title p:first-child{color:var(--mt-home-yellow)!important}.mt-command-title p:last-child{color:#b6c6d4!important;font-size:16px!important;line-height:1.9!important}.mt-command-title span{color:var(--mt-home-teal)!important}.mt-command-actions{padding:8px 0!important}.mt-command-actions a:first-child{background:var(--mt-home-yellow)!important;color:#071d37!important;border-color:transparent!important;border-radius:12px!important}\n.mt-command-visual{padding:0!important}.mt-command{border:1px solid #ffffff1c;border-radius:22px;background:#ffffff0b;backdrop-filter:blur(10px);padding:22px;box-shadow:0 30px 80px #00000035}.mt-command header{display:grid;gap:5px;padding-bottom:17px;border-bottom:1px solid #ffffff17}.mt-command header span{color:var(--mt-home-yellow);font-size:9px}.mt-command header b{font-size:17px;color:#fff}.mt-command-flow{display:grid;gap:9px;margin:16px 0}.mt-command-flow article{display:grid;grid-template-columns:38px 1fr auto;gap:12px;align-items:center;padding:12px;border-radius:12px;background:#ffffff0a;border:1px solid #ffffff12}.mt-command-flow i{font-style:normal;width:35px;height:35px;border-radius:10px;display:grid;place-items:center;background:#11b9b31c;color:#57e3dc;font-size:9px}.mt-command-flow div{display:grid}.mt-command-flow b{font-size:11px}.mt-command-flow span{font-size:8px;color:#9fb2c3}.mt-command-flow em{font-style:normal;font-size:8px;padding:5px 7px;border-radius:999px;background:#e7faf71c;color:#6be8df}.mt-command footer{display:flex;gap:6px;flex-wrap:wrap}.mt-command footer span{font-size:8px;border:1px solid #ffffff19;border-radius:999px;padding:5px 7px;color:#b8c8d5}\n.mt-platform-section{padding:100px 0!important;background:linear-gradient(180deg,#fff,#f6fafc)!important}.mt-platform-grid{padding:0!important}.mt-platform-grid article{border-radius:18px!important;border:1px solid #e1e9ef!important;background:#fff!important;box-shadow:0 12px 38px rgba(8,35,60,.055)!important;min-height:210px!important}.mt-platform-grid article:hover{border-color:#a9ded9!important;transform:translateY(-5px)!important}.mt-platform-grid article>span:first-child{color:var(--mt-home-teal)!important}\n.mt-how-row{padding:100px 0!important;background:#f7fafc!important}.mt-how{padding:0!important}.mt-how strong{background:linear-gradient(135deg,var(--mt-home-teal),#0a7ca2)!important;color:#fff!important}.mt-how h3{font-size:20px!important;color:var(--mt-home-ink)!important}.mt-how p{color:var(--mt-home-muted)!important}\n.mt-stat-row{padding:40px 0!important;background:linear-gradient(110deg,#071d37,#0b3558)!important;color:white!important}.mt-stat-strip{padding:18px 0!important}.mt-stat-strip h2{color:white!important}.mt-stat-strip p{color:#b7c7d4!important}.mt-stat-strip article{border-color:#ffffff18!important}.mt-stat-strip article strong{color:var(--mt-home-yellow)!important}\n.mt-why-section{padding:95px 0!important}.mt-why-card{padding:0!important}.mt-why-card>div{min-height:235px!important;border-radius:20px!important;background:#fff!important;border:1px solid #e2eaf0!important;box-shadow:0 15px 45px rgba(7,40,70,.06)!important}.mt-why-card:nth-child(2){--gold:#2f86f6}.mt-why-card:nth-child(3){--gold:#f2b700}\n.mt-faq-row{padding:95px 0!important;background:#f7fafc!important}.mt-faq{padding:0!important}.mt-faq details{background:#fff!important;border:1px solid #e0e8ee!important;border-radius:14px!important;margin-bottom:9px!important;box-shadow:0 8px 25px rgba(8,35,60,.035)!important}.mt-faq summary{padding:18px!important;color:var(--mt-home-ink)!important;font-weight:850!important}.mt-faq details p{padding:0 18px 18px!important;color:var(--mt-home-muted)!important}\n.mt-contact-row{padding:90px 0!important;background:radial-gradient(circle at 10% 90%,rgba(255,201,40,.17),transparent 25%),linear-gradient(180deg,#fff,#f5fafb)!important}.mt-final-cta{padding:0!important}.mt-final-cta>div{height:100%!important;border-radius:24px!important;background:linear-gradient(135deg,#061d38,#0b4163)!important;box-shadow:0 30px 80px rgba(8,35,60,.18)!important}.mt-final-cta h2{font-size:clamp(32px,4vw,50px)!important}.mt-final-cta a{background:var(--mt-home-yellow)!important;color:#071d37!important;border-radius:12px!important}.mt-contact-card{padding:0!important}.mt-contact-card>div{border-radius:24px!important;border:1px solid #dce7ee!important;box-shadow:0 25px 70px rgba(8,35,60,.10)!important;background:#fff!important}\n@media(max-width:1100px){.mt-home-hero-row{padding-top:130px!important}.mt-dashboard{transform:none}.mt-dashboard-body{grid-template-columns:80px 1fr}.mt-dashboard-grid{grid-template-columns:1fr}.mt-pipeline-card{display:none}}\n@media(max-width:700px){.mt-home-hero-row{padding-top:116px!important;padding-bottom:48px!important}.mt-home-hero-heading h1{font-size:41px!important}.mt-home-hero-heading span{font-size:31px!important}.mt-home-hero-heading p:last-child{font-size:15px!important}.mt-hero-chips{display:grid}.mt-hero-chips span{text-align:center}.mt-dashboard-body{grid-template-columns:1fr}.mt-dashboard-body aside{display:none}.mt-dashboard-body>section{padding:14px}.mt-dashboard-kpis{grid-template-columns:1fr 1fr}.mt-dashboard-kpis article:last-child{grid-column:1/-1}.mt-dashboard-body header em{display:none}.mt-trust-strip span{min-width:calc(50% - 8px)}.mt-command-row,.mt-platform-section,.mt-how-row,.mt-why-section,.mt-faq-row,.mt-contact-row{padding:68px 0!important}.mt-command-flow article{grid-template-columns:34px 1fr}.mt-command-flow em{display:none}}"},"blocks":[]}$document$::jsonb
  );

  update website.sites
  set settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object(
        'siteTitle','ماركتون | منصة تشغيل ونمو لمراكز التدريب',
        'description','ماركتون منصة تشغيل ونمو متخصصة لمراكز ومعاهد التدريب، تربط التسويق والمبيعات والتشغيل والتسجيل والتقارير في مكان واحد.',
        'footerText','ماركتون — منصة تشغيل ونمو متخصصة لمراكز ومعاهد التدريب في المملكة.',
        'freeTrialUrl','/free-trial',
        'freeTrialLabel','ابدأ التجربة المجانية',
        'contactCtaUrl','/free-trial',
        'contactCtaLabel','ابدأ التجربة المجانية',
        'customerLoginUrl','/login',
        'customerLoginLabel','دخول العملاء',
        'country','المملكة العربية السعودية'
      ),
      theme=coalesce(theme,'{}'::jsonb)||jsonb_build_object(
        'navy','#071d37','navySoft','#0b3154','gold','#ffc928',
        'teal','#08b8b1','cyan','#20c6cf','paper','#f7fafc','white','#ffffff'
      ),
      updated_at=now()
  where id=v_site_id;

  update website.pages
  set title='الصفحة الرئيسية',
      menu_label='الرئيسية',
      excerpt='منصة تشغيل ونمو متخصصة لمراكز ومعاهد التدريب في المملكة.',
      content=v_document,
      template_key='visual-builder',
      page_kind='home',
      status='published',
      visibility='public',
      seo_title='ماركتون | منصة تشغيل ونمو لمراكز التدريب',
      seo_description='شغّل مركزك، نمِّ مبيعاتك، وأدر التسويق والعملاء والدورات والتسجيل والتقارير من منصة واحدة متخصصة لقطاع التدريب.',
      canonical_url='/',
      robots='index,follow',
      published_at=coalesce(published_at,now()),
      updated_at=now()
  where id=v_page_id;

  select id into v_document_id
  from website.content_documents
  where site_id=v_site_id and entity_type='page' and entity_id=v_page_id
  limit 1;

  if v_document_id is null then
    insert into website.content_documents(
      site_id,entity_type,entity_id,schema_version,draft_document,published_document,
      draft_updated_at,published_at,created_by_subject_id,updated_by_subject_id,published_by_subject_id
    ) values(v_site_id,'page',v_page_id,1,v_document,v_document,now(),now(),null,null,null);
  else
    update website.content_documents
    set schema_version=1,draft_document=v_document,published_document=v_document,
        draft_updated_at=now(),published_at=now(),updated_at=now()
    where id=v_document_id;
  end if;
end
$$;
commit;
